class Solution {
public:
    long long maxScore(vector<int>& nums1, vector<int>& nums2, int k) {
        int n = (int)nums1.size();
        vector<pair<int,int>> v;
        v.reserve(n);
        for (int i = 0; i < n; i++) {
            v.push_back({nums2[i], nums1[i]});
        }
        sort(v.begin(), v.end(), greater<pair<int,int>>());
        priority_queue<int, vector<int>, greater<int>> pq;
        long long sum = 0;
        long long ans = 0;
        for (auto& p : v) {
            pq.push(p.second);
            sum += p.second;
            if ((int)pq.size() > k) {
                sum -= pq.top();
                pq.pop();
            }
            if ((int)pq.size() == k) {
                long long cur = sum * (long long)p.first;
                if (cur > ans) ans = cur;
            }
        }
        return ans;
    }
};
